    "effects": [
      "This method tags ad requests to receive treatment for users in the European Economic Area (EEA) under the age of consent. It helps facilitate compliance with the General Data Protection Regulation (GDPR).",
      "When set to true, the method disables personalized advertising, including remarketing, for all ad requests. It also disables requests to third-party ad vendors, such as ad measurement pixels and third-party ad servers.",
      "When set to false, the ad request will not receive treatment for users in the European Economic Area (EEA) under the age of consent.",
      "When unspecified, it does not specify whether the ad request should receive treatment for users under the age of consent in the EEA."
    ],
    "preconditions": [
      "The method is called before making an ad request."
    ],
    "postconditions": [],
    "invariants": [],
    "extra_condtions": [
      "The tags to enable the Child-directed setting and setTagForUnderAgeOfConsent() should not both simultaneously be set to true. If they are, the child-directed setting takes precedence."
